CREATE OR REPLACE PACKAGE OPHARAPP.DTKS_REALOKASI_LITTR AS
    FUNCTION get_data (
        p_noagenda      IN  VARCHAR2,
        out_trans_101   OUT SYS_REFCURSOR,
        out_trans_kirim OUT SYS_REFCURSOR,
        out_trans_plnpay OUT SYS_REFCURSOR,
        out_trans_pdl   OUT SYS_REFCURSOR,
        out_master_littr OUT SYS_REFCURSOR,
        out_message     OUT VARCHAR2
    ) RETURN INT;

    PROCEDURE proses_realokasi (
        p_noagenda      IN  VARCHAR2,
        p_no_tiket      IN  VARCHAR2,
        p_new_id_littr  IN  VARCHAR2,
        plogin          IN  VARCHAR2,
        pdb_session     IN  VARCHAR2,
        out_status      OUT VARCHAR2
    );
END DTKS_REALOKASI_LITTR;
/



CREATE OR REPLACE PACKAGE BODY OPHARAPP.DTKS_REALOKASI_LITTR AS

FUNCTION get_data (
    p_noagenda      IN  VARCHAR2,
    out_trans_101   OUT SYS_REFCURSOR,
    out_trans_kirim OUT SYS_REFCURSOR,
    out_trans_plnpay OUT SYS_REFCURSOR,
    out_trans_pdl   OUT SYS_REFCURSOR,
    out_master_littr OUT SYS_REFCURSOR,
    out_message     OUT VARCHAR2
) RETURN INT IS
    v_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM bill52.trans_101 WHERE noagenda = p_noagenda;
    IF v_count = 0 THEN
        out_message := 'Maaf, Noagenda tidak ditemukan di TRANS_101.';
        RETURN 0;
    END IF;

    OPEN out_trans_101 FOR
        SELECT NOAGENDA, TARIF, DAYA, NOREGSLO, ID_LITTR, PETUGASCATAT, TGLCATAT, PAKETSLO 
        FROM bill52.trans_101 
        WHERE noagenda = p_noagenda;

    OPEN out_trans_kirim FOR
        SELECT NOAGENDA, UNITUPI, UNITAP, UNITUP, TGLCATAT, ID_LITTR, NOREGSLO, KIRIM_KE, TGLKIRIM, RC_KIRIM, DESC_KIRIM 
        FROM BILL52.TRANS_KIRIM_KE_LITTR 
        WHERE NOAGENDA = p_noagenda;

    OPEN out_trans_plnpay FOR
        SELECT NOAGENDA, NO_SIP, ID_LITTR, KDBOKING, TGLCATAT, TGLKIRIM, RC_KIRIM, KET_KIRIM 
        FROM BILL52.TRANS_MOHON_PLNPAY 
        WHERE NOAGENDA = p_noagenda;

    OPEN out_trans_pdl FOR
        SELECT NOAGENDA, IDPEL, NAMA, TARIF, DAYA, JENIS_TRANSAKSI, ID_LITTR, NOREGSLO, POSTINGPDL, MSG1 
        FROM BILL52.TRANS_PDL 
        WHERE NOAGENDA = p_noagenda;

    OPEN out_master_littr FOR
        SELECT ID_LITTR, NAMA 
        FROM ERWINBUDI.MASTER_LITTR_SUG2
        ORDER BY ID_LITTR;

    out_message := 'SUKSES';
    RETURN 1;
EXCEPTION WHEN OTHERS THEN
    out_message := SQLERRM;
    RETURN -1;
END get_data;

PROCEDURE proses_realokasi (
    p_noagenda      IN  VARCHAR2,
    p_no_tiket      IN  VARCHAR2,
    p_new_id_littr  IN  VARCHAR2,
    plogin          IN  VARCHAR2,
    pdb_session     IN  VARCHAR2,
    out_status      OUT VARCHAR2
) IS
    v_paketslo NUMBER;
    v_idpel VARCHAR2(30);
    v_unitupi VARCHAR2(10);
BEGIN
    -- 1. Cek PAKETSLO
    BEGIN
        SELECT NVL(PAKETSLO, 0) INTO v_paketslo 
        FROM bill52.trans_101 
        WHERE noagenda = p_noagenda;
    EXCEPTION WHEN NO_DATA_FOUND THEN
        out_status := 'ERROR: Noagenda tidak ditemukan di tabel TRANS_101.';
        RETURN;
    END;

    -- 2. Ambil IDPEL dan UNITUPI untuk LOG_PROSES
    BEGIN
        SELECT IDPEL, UNITUPI INTO v_idpel, v_unitupi 
        FROM BILL52.TRANS_PDL 
        WHERE NOAGENDA = p_noagenda;
    EXCEPTION WHEN OTHERS THEN
        BEGIN
            SELECT IDPEL, UNITUP INTO v_idpel, v_unitupi 
            FROM BILL52.TRANS_101 
            WHERE NOAGENDA = p_noagenda;
        EXCEPTION WHEN OTHERS THEN
            v_idpel := NULL;
            v_unitupi := NULL;
        END;
    END;

    -- 3. Proses Log dan Update berdasarkan PAKETSLO
    IF v_paketslo = 1 THEN
        -- PAKET: 4 Tabel Log and 4 Tabel Update
        -- A. Log TRANS_101
        INSERT INTO BILL52.TRANS_101_LOG (
            NOAGENDA, TGLAGENDA, TGLJAWABAN_101, TGLJATUHTEMPO_101, TGLCATAT, PETUGASCATAT, TGLEDIT, PETUGASEDIT, NOKOLEKTIF, PAKET, VIALAYANAN, FILLER_10, FILLER_11, FILLER_12, MK, JENIS_MK, KET_MOHON_A, KET_MOHON_B, KET_MOHON_C, KET_MOHON_D, KET_MOHON_E, NAMA, KDRUBAH_NOURUTPLG, NOURUTPLG, NPWP, TARIF, KDPT, KDPT_2, DAYA, KDAYA, PNJ, NAMAPNJ, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, LINGKUNGAN, KODEPOS, NOTELP, IDENTITAS, NOIDENTITAS, EMAIL, KEPERLUAN, NODENAH_PLG, FILEBLOB, IDPEL_TETANGGA, UNITUP, IDPEL, TGL_106, TGLLOG, LOGBY, JENIS_TRANSAKSI, NOPEL, DAYAJBST, FAKNPREMIUM, JMLKOLEKTIF, FLAG_RPADMIN, NOTELP_HP, BP_HIBAH, RPBPHIBAH, RPBP
        ) SELECT 
            NOAGENDA, TGLAGENDA, TGLJAWABAN_101, TGLJATUHTEMPO_101, TGLCATAT, PETUGASCATAT, TGLEDIT, PETUGASEDIT, NOKOLEKTIF, PAKET, VIALAYANAN, FILLER_10, FILLER_11, FILLER_12, MK, JENIS_MK, KET_MOHON_A, KET_MOHON_B, KET_MOHON_C, KET_MOHON_D, KET_MOHON_E, NAMA, KDRUBAH_NOURUTPLG, NOURUTPLG, NPWP, TARIF, KDPT, KDPT_2, DAYA, KDAYA, PNJ, NAMAPNJ, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, LINGKUNGAN, KODEPOS, NOTELP, IDENTITAS, NOIDENTITAS, EMAIL, KEPERLUAN, NODENAH_PLG, FILEBLOB, IDPEL_TETANGGA, UNITUP, IDPEL, TGL_106, SYSDATE, 'Notiket: ' || p_no_tiket, JENIS_TRANSAKSI, NOPEL, DAYAJBST, FAKNPREMIUM, JMLKOLEKTIF, FLAG_RPADMIN, NOTELP_HP, BP_HIBAH, RPBPHIBAH, RPBP 
        FROM BILL52.TRANS_101 
        WHERE NOAGENDA = p_noagenda;

        -- B. Log TRANS_KIRIM_KE_LITTR
        INSERT INTO BILL52.TRANS_KIRIM_KE_LITTR_LOG (
            NOAGENDA, TGL_LOG, KD_ALASANSLO, UNITAP, UNITUP, UNITUPI, NOREGSLO, NOREGTLO, KIRIM_KE, VENDOR_KE, TGLCATAT, TGLKIRIM, KETERANGAN, TGLFEEDBACK, TGLFLAGTDKSIAP, ALASANTIDAKSIAP, TGLPENANGGUHAN, ALASANPENANGGUHAN, TGLKIRIMPENANGGUHAN, TGL_TERBIT, TGL_KADALUARSA, URL, FLAGPLN, TGLFLAGPLN, PETUGASFLAGPLN, RPSLO, RC_KIRIM, DESC_KIRIM, TGLJTTEMPOFB, FLAGTIDAKSIAP, ID_LITTR, KD_ALASAN, TGLSIAPINSTALASI, FLAGTANGGUH, RC_TANGGUH, DESC_TANGGUH, FLAGNYALA, TGLNYALA, TGLKIRIMNYALA, RC_NYALA, DESC_NYALA, FLAGRESTITUSI, TGLRESITUSI, TGLKIRIMRESTITUSI, RC_RESTITUSI, DESC_RESTITUSI, FLAGSIAPSAMBUNG, TGLSIAPSAMBUNG, TGLKIRIMSIAPSAMBUNG, RC_SIAPSAMBUNG, DESC_SIAPSAMBUNG, TGLFLAGTDKSIAP_LITTR, ALASANTDKSIAP_LITTR, FLAGBLOKING_FB, TGLBLOKING_FB, TGLKIRIM_BLOKING_FB, FLAGBLOKING_PLN, TGLBLOKING_PLN, TGLKIRIM_BLOKING_PLN, KD_BLOKING, TGLJTTEMPOLITTRKERJA
        ) SELECT 
            NOAGENDA, SYSDATE, KD_ALASANSLO, UNITAP, UNITUP, UNITUPI, NOREGSLO, NOREGTLO, KIRIM_KE, VENDOR_KE, TGLCATAT, TGLKIRIM, KETERANGAN, TGLFEEDBACK, TGLFLAGTDKSIAP, ALASANTIDAKSIAP, TGLPENANGGUHAN, ALASANPENANGGUHAN, TGLKIRIMPENANGGUHAN, TGL_TERBIT, TGL_KADALUARSA, URL, FLAGPLN, TGLFLAGPLN, PETUGASFLAGPLN, RPSLO, RC_KIRIM, DESC_KIRIM, TGLJTTEMPOFB, FLAGTIDAKSIAP, ID_LITTR, KD_ALASAN, TGLSIAPINSTALASI, FLAGTANGGUH, RC_TANGGUH, DESC_TANGGUH, FLAGNYALA, TGLNYALA, TGLKIRIMNYALA, RC_NYALA, DESC_NYALA, FLAGRESTITUSI, TGLRESITUSI, TGLKIRIMRESTITUSI, RC_RESTITUSI, DESC_RESTITUSI, FLAGSIAPSAMBUNG, TGLSIAPSAMBUNG, TGLKIRIMSIAPSAMBUNG, RC_SIAPSAMBUNG, DESC_SIAPSAMBUNG, TGLFLAGTDKSIAP_LITTR, ALASANTDKSIAP_LITTR, FLAGBLOKING_FB, TGLBLOKING_FB, TGLKIRIM_BLOKING_FB, FLAGBLOKING_PLN, TGLBLOKING_PLN, TGLKIRIM_BLOKING_PLN, KD_BLOKING, TGLJTTEMPOLITTRKERJA 
        FROM BILL52.TRANS_KIRIM_KE_LITTR 
        WHERE NOAGENDA = p_noagenda;

        -- C. Log TRANS_MOHON_PLNPAY
        INSERT INTO OPHARAPP.TRANS_MOHON_PLNPAY_LOG (
            NOAGENDA, NO_SIP, KDBOKING, KDBANK, MERCHANT, KDMERCHANT, TGLCATAT, ID_LITTR, RPUJL, RPBP, RPSLO, TGLKIRIM, TGLJTTEMPO, REFNUM, TGLBOKING, RC_KIRIM, KET_KIRIM, TGLKIRIM_BATAL, RC_BATAL, KET_BATAL, STATUSPLNPAY, TGLLOG, LOGBY
        ) SELECT 
            NOAGENDA, NO_SIP, KDBOKING, KDBANK, MERCHANT, KDMERCHANT, TGLCATAT, ID_LITTR, RPUJL, RPBP, RPSLO, TGLKIRIM, TGLJTTEMPO, REFNUM, TGLBOKING, RC_KIRIM, KET_KIRIM, TGLKIRIM_BATAL, RC_BATAL, KET_BATAL, STATUSPLNPAY, SYSDATE, 'Notiket: ' || p_no_tiket 
        FROM BILL52.TRANS_MOHON_PLNPAY 
        WHERE NOAGENDA = p_noagenda;

        -- D. Log TRANS_PDL
        INSERT INTO BILL52.TRANS_PDL_LOG (
            NOMORPDL, KDPEMBMETER, DAYA, KDAYA, FRT, NAMAPNJ, KOGOL, KDJENIS_SL, PEMDA, KDINKASO, LETAKDESA, MEREK_PEMBATAS, KODEDESA, TEGANGAN_SL, TYPE_PEMBATAS, KDBPT, MK, KDRUBAH_NOURUTPLG, KDAM, MEREK_SAKLARWAKTU, KDPT, KTEGANGAN_SL, KDPT_2, LETAKAPP, KDPENGGERAK, KDREKG, KDPENGUKURAN, KELASDESA, TARIF, TYPE_SAKLARWAKTU, PNJ, KDPSL, FJN, REF_KDPPJ, KDIND, KDKLP, KDUJL, LINGKUNGAN, IDPEL, THBLMUT, JENIS_MK, UNITUPI, UNITAP, UNITUP, UNITKJ, POSTINGPDL, TGLENTRIPDL, TGLRUBAH_MK, TGLCATAT, CATATBY, TGLUPDATE, UPDATEBY, TGLPEREMAJAAN, PEREMAJAANBY, NAMA, NOURUTPLG, NPWP, KDTARIP_CIS, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, KODEPOS, KDANGSA, RPANGSA, LAMAANGSA, THBLANGS1A, ANGSKEA, KDANGSB, RPANGSB, LAMAANGSB, THBLANGS1B, ANGSKEB, KDANGSC, RPANGSC, LAMAANGSC, THBLANGS1C, ANGSKEC, NOBP, TGLBP, RPBP, NOUJL, TGLUJL, RPUJL, KDDK, KDBACAMETER, SUBKOGOL, COPYREK, KDMETERAI, KDPPJ, LOKETTGK, KDKVAMAKS, DAYABPT, KDDAYABPT, TGLPASANG_KWH, MEREK_KWH, TYPE_KWH, NOMETER_KWH, THTERA_KWH, THBUAT_KWH, KDDK_AWAL_LWBP, KDDK_AWAL_WBP, NOPABRIK_KWH, NOREGISTER_KWH, FASA_KWH, STAND_CABUT_LWBP, STAND_CABUT_WBP, KDPEMBMETER_KWH, TGLPASANG_KVARH, MEREK_KVARH, TYPE_KVARH, NOMETER_KVARH, THTERA_KVARH, THBUAT_KVARH, KDDK_AWAL_KVARH, NOPABRIK_KVARH, NOREGISTER_KVARH, FASA_KVARH, STAND_CABUT_KVARH, KDPEMBMETER_KVARH, TGLPASANG_KVAMAKS, MEREK_KVAMAKS, TYPE_KVAMAKS, NOMETER_KVAMAKS, THTERA_KVAMAKS, THBUAT_KVAMAKS, KDDK_AWAL_KVAMAKS, NOPABRIK_KVAMAKS, NOREGISTER_KVAMAKS, FASA_KVAMAKS, STAND_CABUT_KVAMAKS, KDPEMBMETER_KVAMAKS, TGLPASANG_CTPTKWH, CT_PRIMER_KWH, CT_SEKUNDER_KWH, PT_PRIMER_KWH, PT_SEKUNDER_KWH, KONSTANTA_KWH, FAKMKWH, TGLPASANG_CTPTKVARH, CT_PRIMER_KVARH, CT_SEKUNDER_KVARH, PT_PRIMER_KVARH, PT_SEKUNDER_KVARH, KONSTANTA_KVARH, FAKMKVARH, TGLPASANG_CTPTKVAMAKS, CT_PRIMER_KVAMAKS, CT_SEKUNDER_KVAMAKS, PT_PRIMER_KVAMAKS, PT_SEKUNDER_KVAMAKS, KONSTANTA_KVAMAKS, FAKMKVAM, THTERA_PEMBATAS, NOPEMBATAS, TGLPASANG_PEMBATAS, THBUAT_PEMBATAS, JENIS_PEMBATAS, UKURANSETTING_PEMBATAS, ARUS_PEMBATAS, TEGANGAN_PEMBATAS, FASA_PEMBATAS, TGLPASANG_SAKLARWAKTU, NOMOR_SAKLARWAKTU, THBUAT_SAKLARWAKTU, THTERA_SAKLARWAKTU, TGLPASANG_SL, KDGARDU, NOTIANG, NOSL, PANJANG_SL, FASA_SL, KDIJIN_WBP, KDINSTALATIR, KODELOKASIDESA, KEL_DESA, KECAMATAN, KODYA_KAB, MSG1, MSG2, BATCHID, F_KETBP, F_KETUJL, KDKOMERSIL, LWBP, WBP, KDGMP, NOSPJBTL, TGLSPJBTL, J_ARUSKWH, G_STANGS1, G_STANGS2, G_STANGS3, G_NOBUKTI1, G_TGLBUKTI1, G_NOBUKTI2, G_TGLBUKTI2, G_NOBUKTI3, G_TGLBUKTI3, UBAHGANTINAMA, TGL_PENGESAHAN, SAH_BY, NOAGENDA, NOPEL, FAKNPREMIUM, PEMASARAN, STS_PRIMA, DAYAJBST, KDDAYAJBST, TGLAWLJBST, TGLAKHJBST, TGLBYREMIN, RPEMINJBST, KWHEMINJBST, BTSKWHREG, KDBEDAJBST, NOKUITEMIN, KDPROSES, KDPDPJ, NOTELP, KDINVOICE, KOORDINATX, KOORDINATY, NO_PABRIK, KOREKSIKE, LOG_BY, TGL_LOG, IDPEL_TTG, TYPE_CT_KWH, TYPE_CT_KVARH, TYPE_CT_KVAMAX, RPSEWATRAFO, NOIDENTITAS, NOKK, NOTRAFO
        ) SELECT 
            NOMORPDL, KDPEMBMETER, DAYA, KDAYA, FRT, NAMAPNJ, KOGOL, KDJENIS_SL, PEMDA, KDINKASO, LETAKDESA, MEREK_PEMBATAS, KODEDESA, TEGANGAN_SL, TYPE_PEMBATAS, KDBPT, MK, KDRUBAH_NOURUTPLG, KDAM, MEREK_SAKLARWAKTU, KDPT, KTEGANGAN_SL, KDPT_2, LETAKAPP, KDPENGGERAK, KDREKG, KDPENGUKURAN, KELASDESA, TARIF, TYPE_SAKLARWAKTU, PNJ, KDPSL, FJN, REF_KDPPJ, KDIND, KDKLP, KDUJL, LINGKUNGAN, IDPEL, THBLMUT, JENIS_MK, UNITUPI, UNITAP, UNITUP, UNITKJ, POSTINGPDL, TGLENTRIPDL, TGLRUBAH_MK, TGLCATAT, CATATBY, TGLUPDATE, UPDATEBY, TGLPEREMAJAAN, PEREMAJAANBY, NAMA, NOURUTPLG, NPWP, KDTARIP_CIS, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, KODEPOS, KDANGSA, RPANGSA, LAMAANGSA, THBLANGS1A, ANGSKEA, KDANGSB, RPANGSB, LAMAANGSB, THBLANGS1B, ANGSKEB, KDANGSC, RPANGSC, LAMAANGSC, THBLANGS1C, ANGSKEC, NOBP, TGLBP, RPBP, NOUJL, TGLUJL, RPUJL, KDDK, KDBACAMETER, SUBKOGOL, COPYREK, KDMETERAI, KDPPJ, LOKETTGK, KDKVAMAKS, DAYABPT, KDDAYABPT, TGLPASANG_KWH, MEREK_KWH, TYPE_KWH, NOMETER_KWH, THTERA_KWH, THBUAT_KWH, KDDK_AWAL_LWBP, KDDK_AWAL_WBP, NOPABRIK_KWH, NOREGISTER_KWH, FASA_KWH, STAND_CABUT_LWBP, STAND_CABUT_WBP, KDPEMBMETER_KWH, TGLPASANG_KVARH, MEREK_KVARH, TYPE_KVARH, NOMETER_KVARH, THTERA_KVARH, THBUAT_KVARH, KDDK_AWAL_KVARH, NOPABRIK_KVARH, NOREGISTER_KVARH, FASA_KVARH, STAND_CABUT_KVARH, KDPEMBMETER_KVARH, TGLPASANG_KVAMAKS, MEREK_KVAMAKS, TYPE_KVAMAKS, NOMETER_KVAMAKS, THTERA_KVAMAKS, THBUAT_KVAMAKS, KDDK_AWAL_KVAMAKS, NOPABRIK_KVAMAKS, NOREGISTER_KVAMAKS, FASA_KVAMAKS, STAND_CABUT_KVAMAKS, KDPEMBMETER_KVAMAKS, TGLPASANG_CTPTKWH, CT_PRIMER_KWH, CT_SEKUNDER_KWH, PT_PRIMER_KWH, PT_SEKUNDER_KWH, KONSTANTA_KWH, FAKMKWH, TGLPASANG_CTPTKVARH, CT_PRIMER_KVARH, CT_SEKUNDER_KVARH, PT_PRIMER_KVARH, PT_SEKUNDER_KVARH, KONSTANTA_KVARH, FAKMKVARH, TGLPASANG_CTPTKVAMAKS, CT_PRIMER_KVAMAKS, CT_SEKUNDER_KVAMAKS, PT_PRIMER_KVAMAKS, PT_SEKUNDER_KVAMAKS, KONSTANTA_KVAMAKS, FAKMKVAM, THTERA_PEMBATAS, NOPEMBATAS, TGLPASANG_PEMBATAS, THBUAT_PEMBATAS, JENIS_PEMBATAS, UKURANSETTING_PEMBATAS, ARUS_PEMBATAS, TEGANGAN_PEMBATAS, FASA_PEMBATAS, TGLPASANG_SAKLARWAKTU, NOMOR_SAKLARWAKTU, THBUAT_SAKLARWAKTU, THTERA_SAKLARWAKTU, TGLPASANG_SL, KDGARDU, NOTIANG, NOSL, PANJANG_SL, FASA_SL, KDIJIN_WBP, KDINSTALATIR, KODELOKASIDESA, KEL_DESA, KECAMATAN, KODYA_KAB, MSG1, MSG2, BATCHID, F_KETBP, F_KETUJL, KDKOMERSIL, LWBP, WBP, KDGMP, NOSPJBTL, TGLSPJBTL, J_ARUSKWH, G_STANGS1, G_STANGS2, G_STANGS3, G_NOBUKTI1, G_TGLBUKTI1, G_NOBUKTI2, G_TGLBUKTI2, G_NOBUKTI3, G_TGLBUKTI3, UBAHGANTINAMA, TGL_PENGESAHAN, SAH_BY, NOAGENDA, NOPEL, FAKNPREMIUM, PEMASARAN, STS_PRIMA, DAYAJBST, KDDAYAJBST, TGLAWLJBST, TGLAKHJBST, TGLBYREMIN, RPEMINJBST, KWHEMINJBST, BTSKWHREG, KDBEDAJBST, NOKUITEMIN, KDPROSES, KDPDPJ, NOTELP, KDINVOICE, KOORDINATX, KOORDINATY, NO_PABRIK, (SELECT MAX(NVL(KOREKSIKE,0))+1 FROM BILL52.TRANS_PDL_LOG WHERE NOAGENDA=A.NOAGENDA), 'Notiket: ' || p_no_tiket, SYSDATE, IDPEL_TTG, TYPE_CT_KWH, TYPE_CT_KVARH, TYPE_CT_KVAMAX, RPSEWATRAFO, NOIDENTITAS, NOKK, NOTRAFO 
        FROM BILL52.TRANS_PDL A 
        WHERE NOAGENDA = p_noagenda;

        -- E. Update Tabel
