        UPDATE BILL52.TRANS_MOHON_PLNPAY SET ID_LITTR = p_new_id_littr WHERE NOAGENDA = p_noagenda;
        UPDATE BILL52.TRANS_PDL SET ID_LITTR = p_new_id_littr WHERE NOAGENDA = p_noagenda;
        UPDATE BILL52.TRANS_KIRIM_KE_LITTR 
        SET ID_LITTR = p_new_id_littr, TGLKIRIM = NULL, RC_KIRIM = NULL, DESC_KIRIM = NULL 
        WHERE NOAGENDA = p_noagenda;

    ELSE
        -- NON-PAKET: 2 Tabel Log and 2 Tabel Update
        -- A. Log TRANS_101
        INSERT INTO BILL52.TRANS_101_LOG (
            NOAGENDA, TGLAGENDA, TGLJAWABAN_101, TGLJATUHTEMPO_101, TGLCATAT, PETUGASCATAT, TGLEDIT, PETUGASEDIT, NOKOLEKTIF, PAKET, VIALAYANAN, FILLER_10, FILLER_11, FILLER_12, MK, JENIS_MK, KET_MOHON_A, KET_MOHON_B, KET_MOHON_C, KET_MOHON_D, KET_MOHON_E, NAMA, KDRUBAH_NOURUTPLG, NOURUTPLG, NPWP, TARIF, KDPT, KDPT_2, DAYA, KDAYA, PNJ, NAMAPNJ, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, LINGKUNGAN, KODEPOS, NOTELP, IDENTITAS, NOIDENTITAS, EMAIL, KEPERLUAN, NODENAH_PLG, FILEBLOB, IDPEL_TETANGGA, UNITUP, IDPEL, TGL_106, TGLLOG, LOGBY, JENIS_TRANSAKSI, NOPEL, DAYAJBST, FAKNPREMIUM, JMLKOLEKTIF, FLAG_RPADMIN, NOTELP_HP, BP_HIBAH, RPBPHIBAH, RPBP
        ) SELECT 
            NOAGENDA, TGLAGENDA, TGLJAWABAN_101, TGLJATUHTEMPO_101, TGLCATAT, PETUGASCATAT, TGLEDIT, PETUGASEDIT, NOKOLEKTIF, PAKET, VIALAYANAN, FILLER_10, FILLER_11, FILLER_12, MK, JENIS_MK, KET_MOHON_A, KET_MOHON_B, KET_MOHON_C, KET_MOHON_D, KET_MOHON_E, NAMA, KDRUBAH_NOURUTPLG, NOURUTPLG, NPWP, TARIF, KDPT, KDPT_2, DAYA, KDAYA, PNJ, NAMAPNJ, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, LINGKUNGAN, KODEPOS, NOTELP, IDENTITAS, NOIDENTITAS, EMAIL, KEPERLUAN, NODENAH_PLG, FILEBLOB, IDPEL_TETANGGA, UNITUP, IDPEL, TGL_106, SYSDATE, 'Notiket: ' || p_no_tiket, JENIS_TRANSAKSI, NOPEL, DAYAJBST, FAKNPREMIUM, JMLKOLEKTIF, FLAG_RPADMIN, NOTELP_HP, BP_HIBAH, RPBPHIBAH, RPBP 
        FROM BILL52.TRANS_101 
        WHERE NOAGENDA = p_noagenda;

        -- B. Log TRANS_PDL
        INSERT INTO BILL52.TRANS_PDL_LOG 
        SELECT NOMORPDL, KDPEMBMETER, DAYA, KDAYA, FRT, NAMAPNJ, KOGOL, KDJENIS_SL, PEMDA, KDINKASO, LETAKDESA, MEREK_PEMBATAS, KODEDESA, TEGANGAN_SL, TYPE_PEMBATAS, KDBPT, MK, KDRUBAH_NOURUTPLG, KDAM, MEREK_SAKLARWAKTU, KDPT, KTEGANGAN_SL, KDPT_2, LETAKAPP, KDPENGGERAK, KDREKG, KDPENGUKURAN, KELASDESA, TARIF, TYPE_SAKLARWAKTU, PNJ, KDPSL, FJN, REF_KDPPJ, KDIND, KDKLP, KDUJL, LINGKUNGAN, IDPEL, THBLMUT, JENIS_MK, UNITUPI, UNITAP, UNITUP, UNITKJ, POSTINGPDL, TGLENTRIPDL, TGLRUBAH_MK, TGLCATAT, CATATBY, TGLUPDATE, UPDATEBY, TGLPEREMAJAAN, PEREMAJAANBY, NAMA, NOURUTPLG, NPWP, KDTARIP_CIS, NOBANG, KETNOBANG, RT, RW, NODLMRT, KETNODLMRT, KODEPOS, KDANGSA, RPANGSA, LAMAANGSA, THBLANGS1A, ANGSKEA, KDANGSB, RPANGSB, LAMAANGSB, THBLANGS1B, ANGSKEB, KDANGSC, RPANGSC, LAMAANGSC, THBLANGS1C, ANGSKEC, NOBP, TGLBP, RPBP, NOUJL, TGLUJL, RPUJL, KDDK, KDBACAMETER, SUBKOGOL, COPYREK, KDMETERAI, KDPPJ, LOKETTGK, KDKVAMAKS, DAYABPT, KDDAYABPT, TGLPASANG_KWH, MEREK_KWH, TYPE_KWH, NOMETER_KWH, THTERA_KWH, THBUAT_KWH, KDDK_AWAL_LWBP, KDDK_AWAL_WBP, NOPABRIK_KWH, NOREGISTER_KWH, FASA_KWH, STAND_CABUT_LWBP, STAND_CABUT_WBP, KDPEMBMETER_KWH, TGLPASANG_KVARH, MEREK_KVARH, TYPE_KVARH, NOMETER_KVARH, THTERA_KVARH, THBUAT_KVARH, KDDK_AWAL_KVARH, NOPABRIK_KVARH, NOREGISTER_KVARH, FASA_KVARH, STAND_CABUT_KVARH, KDPEMBMETER_KVARH, TGLPASANG_KVAMAKS, MEREK_KVAMAKS, TYPE_KVAMAKS, NOMETER_KVAMAKS, THTERA_KVAMAKS, THBUAT_KVAMAKS, KDDK_AWAL_KVAMAKS, NOPABRIK_KVAMAKS, NOREGISTER_KVAMAKS, FASA_KVAMAKS, STAND_CABUT_KVAMAKS, KDPEMBMETER_KVAMAKS, TGLPASANG_CTPTKWH, CT_PRIMER_KWH, CT_SEKUNDER_KWH, PT_PRIMER_KWH, PT_SEKUNDER_KWH, KONSTANTA_KWH, FAKMKWH, TGLPASANG_CTPTKVARH, CT_PRIMER_KVARH, CT_SEKUNDER_KVARH, PT_PRIMER_KVARH, PT_SEKUNDER_KVARH, KONSTANTA_KVARH, FAKMKVARH, TGLPASANG_CTPTKVAMAKS, CT_PRIMER_KVAMAKS, CT_SEKUNDER_KVAMAKS, PT_PRIMER_KVAMAKS, PT_SEKUNDER_KVAMAKS, KONSTANTA_KVAMAKS, FAKMKVAM, THTERA_PEMBATAS, NOPEMBATAS, TGLPASANG_PEMBATAS, THBUAT_PEMBATAS, JENIS_PEMBATAS, UKURANSETTING_PEMBATAS, ARUS_PEMBATAS, TEGANGAN_PEMBATAS, FASA_PEMBATAS, TGLPASANG_SAKLARWAKTU, NOMOR_SAKLARWAKTU, THBUAT_SAKLARWAKTU, THTERA_SAKLARWAKTU, TGLPASANG_SL, KDGARDU, NOTIANG, NOSL, PANJANG_SL, FASA_SL, KDIJIN_WBP, KDINSTALATIR, KODELOKASIDESA, KEL_DESA, KECAMATAN, KODYA_KAB, MSG1, MSG2, BATCHID, F_KETBP, F_KETUJL, KDKOMERSIL, LWBP, WBP, KDGMP, NOSPJBTL, TGLSPJBTL, J_ARUSKWH, G_STANGS1, G_STANGS2, G_STANGS3, G_NOBUKTI1, G_TGLBUKTI1, G_NOBUKTI2, G_TGLBUKTI2, G_NOBUKTI3, G_TGLBUKTI3, UBAHGANTINAMA, TGL_PENGESAHAN, SAH_BY, NOAGENDA, NOPEL, FAKNPREMIUM, PEMASARAN, STS_PRIMA, DAYAJBST, KDDAYAJBST, TGLAWLJBST, TGLAKHJBST, TGLBYREMIN, RPEMINJBST, KWHEMINJBST, BTSKWHREG, KDBEDAJBST, NOKUITEMIN, KDPROSES, KDPDPJ, NOTELP, KDINVOICE, KOORDINATX, KOORDINATY, NO_PABRIK,(SELECT MAX(NVL(KOREKSIKE,0))+1 FROM BILL52.TRANS_PDL_LOG WHERE NOAGENDA=A.NOAGENDA) KOREKSIKE, 'Notiket: {parameter nomor tiket}' LOG_BY, SYSDATE TGL_LOG, IDPEL_TTG, TYPE_CT_KWH, TYPE_CT_KVARH, TYPE_CT_KVAMAX, RPSEWATRAFO, NOIDENTITAS, NOKK, NOTRAFO FROM BILL52.TRANS_PDL A WHERE NOAGENDA=p_noagenda;

        -- C. Update Tabel
        UPDATE BILL52.TRANS_101 SET ID_LITTR = p_new_id_littr WHERE NOAGENDA = p_noagenda;
        UPDATE BILL52.TRANS_PDL SET ID_LITTR = p_new_id_littr WHERE NOAGENDA = p_noagenda;
    END IF;

    -- 4. Log Akhir Proses
    INSERT INTO OPHARAPP.DTKS_LOG_PROSES (
        NO_TIKET, JENIS_TRANSAKSI, NO_PELANGGAN, TGLPROSES, UNITUPI, LOGIN, DB_SESSION
    ) VALUES (
        p_no_tiket, 'Realokasi LITTR', v_idpel, SYSDATE, v_unitupi, plogin, pdb_session
    );

    COMMIT;
    out_status := 'SUCCESS';
EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    out_status := 'ERROR: ' || SQLERRM;
END proses_realokasi;

END DTKS_REALOKASI_LITTR;
